    charts.da = new Chart($('chDA'), { type: 'bar', data: { labels: rows.map(function (x) { return x.c.name; }), datasets: [{ data: rows.map(function (x) { return x.r * 100; }), backgroundColor: rows.map(function (x) { return H.color(x.c.ticker); }), borderRadius: 3, maxBarThickness: horiz ? 22 : 46 }] }, options: { indexAxis: horiz ? 'y' : 'x', layout: { padding: horiz ? { right: 30 } : { top: 18 } }, scales: horiz ? { x: vAxis, y: cAxis } : { x: cAxis, y: vAxis }, plugins: { tooltip: { callbacks: { label: function (ctx) { var x = rows[ctx.dataIndex]; return x.c.name + ': D&A ' + H.money(x.q.ttm.da).replace(/<[^>]+>/g, '') + ' / capex ' + H.money(x.q.ttm.capex_cash).replace(/<[^>]+>/g, '') + ' · ' + H.date(x.q.end); } } } } }, plugins: [horiz ? refH : ref, horiz ? labH : lab] });
