      var capCard = cap != null ? H.src({ title: c.name + ' · capex ' + x.fy, rows: [[t('Nivel', 'Tier'), 'T1 · SEC (XBRL)'], [t('Etiqueta XBRL', 'XBRL tag'), fy.m.capex_cash[1]], [t('Presentación', 'Filing'), fy.m.capex_cash[2].join(', ')]], url: H.edgar(c.cik, fy.m.capex_cash[2][0]) }) : '';
      return '<b>' + esc(c.name) + '</b>: ' + t('potencia activa ', 'active power ') + H.mw(x.from.mw, x.from.qualifier) + ' → ' + H.mw(x.to.mw, x.to.qualifier) + H.cite(c.name + ' · ' + t('potencia activa', 'active power'), x.src) + ' (' + H.date(x.from.asOf) + ' → ' + H.date(x.to.asOf) + '), ' + t('es decir ', 'that is ') + H.mw(add) + t(' añadidos; capex en efectivo ', ' added; cash capex ') + (cap != null ? H.money(cap) + capCard + t(' en ', ' in ') + x.fy : H.ntCell(c.ticker, 'capex_cash')) + (cap != null ? ' ⇒ <b>≈ US$ ' + H.num(cap / 1e9 / (add / 1000), 1) + (H.lang === 'es' ? ' mil M' : ' bn') + t(' por GW añadido', ' per GW added') + '</b> ' + H.tier('C') + ' ' + t('(aproximado: los extremos son «aproximadamente» y «más de»)', '(approximate: the ends are "approximately" and "over")') : '') + '. ' + esc(x['note_' + H.lang]);
